/* app50: Document Screener — upload any document (PDF, Word .docx, images/scans, text, email, HTML) and screen it with a fine-tooth comb.
   Layer 1 (instant, in the browser, nothing leaves the page): text extraction, document-type detection, every date and deadline, relative timelines
   ("within 17 days") turned into calendar dates from an anchor date, money and percentages, parties, blanks left unfilled, 90+ clause/risk rules
   (mortgage, real estate, lender, vendor and employment contracts), hidden-content forensics (white or hidden Word text, tracked changes, comments,
   macros, external links, PDF JavaScript, embedded files, edits after creation, editing-tool producers, tiny or off-page text, zero-width and
   bidi-override characters, look-alike letters) and fraud red flags for bank statements, paystubs and tax returns.
   Layer 2 (on a click, through in-page Claude): chunked clause-by-clause deep screen, then a synthesis: executive and client summaries, risk score,
   key terms, timeline, obligations by party, hidden or unusual terms, missing items, negotiation points and questions. Scanned pages and photos
   go to Claude as images. SSNs, account and routing numbers are masked before anything is sent (on by default).
   Also: Ask-the-document chat with quotes, two-document compare (what changed and who it favors), highlighted reader, Word report, .ics deadlines,
   CSV timeline, Handoff Board cards, Gmail draft of the summary to Steven, screening history, agent tools, a playbook, AI seats and a runbook. */
const DS_LIB={pdf:"https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js",pdfw:"https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js",zip:"https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js"};
const dsScript=src=>new Promise((ok,no)=>{const s0=document.querySelector(`script[data-ds="${src}"]`);if(s0){if(s0.dataset.ok)return ok();s0.addEventListener("load",()=>ok());s0.addEventListener("error",()=>no(new Error("load failed")));return}const s=document.createElement("script");s.src=src;s.dataset.ds=src;s.onload=()=>{s.dataset.ok=1;ok()};s.onerror=()=>no(new Error("Could not load "+src.split("/").pop()+" (offline or blocked)."));document.head.appendChild(s)});
async function dsPdfLib(){if(!window.pdfjsLib){await dsScript(DS_LIB.pdf)}window.pdfjsLib.GlobalWorkerOptions.workerSrc=DS_LIB.pdfw;return window.pdfjsLib}
async function dsZipLib(){if(!window.JSZip)await dsScript(DS_LIB.zip);return window.JSZip}
const DS_S={docs:[],cur:-1,ai:null,busy:false,ctl:null,chat:[]};
const dsOpt=()=>Object.assign({mask:true,anchor:"",big:5000,deep:"default"},store.get("ds_opt",{}));
const dsSetOpt=o=>store.set("ds_opt",Object.assign(dsOpt(),o));
const dsDoc=()=>DS_S.docs[DS_S.cur]||null;
