const dsLatin1=u8=>{let s="";for(let i=0;i<u8.length;i+=65536)s+=String.fromCharCode.apply(null,u8.subarray(i,i+65536));return s};
async function dsReadPdf(file,buf){const lib=await dsPdfLib();const u8=new Uint8Array(buf);const raw=dsLatin1(u8);
 const pdf=await lib.getDocument({data:u8.slice(0)}).promise;const meta=await pdf.getMetadata().catch(()=>({}));const info=(meta&&meta.info)||{};
 const F=[];const pages=[];const scanned=[];let tiny=0,off=0;const fontsPer=[];
 for(let p=1;p<=pdf.numPages;p++){const pg=await pdf.getPage(p);const vp=pg.getViewport({scale:1});const tc=await pg.getTextContent();let line=[],lastY=null;const out=[];const fonts=new Set();
  tc.items.forEach(it=>{if(!("str" in it))return;const y=Math.round(it.transform[5]),x=it.transform[4],h=Math.hypot(it.transform[2],it.transform[3]);fonts.add(it.fontName);
   if(it.str.trim()){if(h>0&&h<3.5)tiny++;if(x<-5||x>vp.width+5||y<-5||y>vp.height+5)off++}
   if(lastY!==null&&Math.abs(y-lastY)>2){out.push(line.join(""));line=[]}line.push(it.str+(it.hasEOL?"\n":""));lastY=y});
  out.push(line.join(""));const t=out.join("\n").replace(/\n{3,}/g,"\n\n");pages.push(t);fontsPer.push(fonts.size);if(t.replace(/\s/g,"").length<40)scanned.push(p);
  const an=await pg.getAnnotations().catch(()=>[]);an.forEach(a=>{if(a.subtype==="Text"||a.subtype==="FreeText"||a.subtype==="Popup")F.push({k:"pdf_comment",sev:2,t:`Page ${p}: a comment/sticky note is attached`,q:String(a.contents||(a.contentsObj||{}).str||"").slice(0,200)});if(a.subtype==="Link"&&a.url)F.push({k:"pdf_link",sev:1,t:`Page ${p}: link to ${a.url.slice(0,80)}`,q:""});if(a.subtype==="Widget"&&a.fieldValue!=null&&String(a.fieldValue).trim())F.push({k:"pdf_field",sev:1,t:`Page ${p}: form field "${a.fieldName||""}" = ${String(a.fieldValue).slice(0,60)}`,q:""})})}
 const eof=(raw.match(/%%EOF/g)||[]).length;const prod=[info.Producer,info.Creator].filter(Boolean).join(" / ");
 if(eof>1)F.push({k:"pdf_incremental",sev:3,t:`Saved ${eof} times (incremental updates): content was changed after the file was first created`,q:"For a bank statement, paystub, tax form or anything 'from the source', ask for a fresh download or verify directly (VOD, 4506-C, payroll)."});
 if(/\/JavaScript|\/JS\s*[(<\/]/.test(raw))F.push({k:"pdf_js",sev:3,t:"Contains JavaScript (can change what is shown or act when opened)",q:"Do not trust on-screen values; request a flattened copy."});
 if(/\/EmbeddedFile/.test(raw))F.push({k:"pdf_embed",sev:2,t:"Has embedded/attached files inside the PDF",q:"Open the attachments panel and screen each one."});
 if(/\/AcroForm/.test(raw))F.push({k:"pdf_form",sev:1,t:"Fillable form: values can be edited by anyone with the file",q:""});
 if(/\/Encrypt/.test(raw))F.push({k:"pdf_enc",sev:1,t:"Encrypted / permission-restricted PDF",q:""});
 if(/\/OpenAction|\/Launch|\/SubmitForm|\/URI\s*\(/.test(raw)&&/\/OpenAction|\/Launch|\/SubmitForm/.test(raw))F.push({k:"pdf_action",sev:3,t:"Has an automatic action (OpenAction / Launch / SubmitForm)",q:""});
 if(/photoshop|illustrator|gimp|canva|ilovepdf|smallpdf|sejda|pdfescape|pdf-xchange|foxit phantom|nitro|pdffiller|dochub|inkscape|word|libreoffice|google docs|pages/i.test(prod))F.push({k:"pdf_producer",sev:2,t:`Made or last saved with: ${prod}`,q:"Normal for a contract you drafted; a red flag for a bank statement, paystub, W-2, tax transcript or award letter that should come straight from the source."});
 const cd=String(info.CreationDate||""),md=String(info.ModDate||"");if(cd&&md&&cd.slice(2,16)!==md.slice(2,16))F.push({k:"pdf_moddate",sev:2,t:`Modified after creation (created ${dsPdfDate(cd)}, modified ${dsPdfDate(md)})`,q:""});
 if(tiny)F.push({k:"pdf_tiny",sev:3,t:`${tiny} pieces of text are smaller than 3.5 pt (practically invisible when printed)`,q:"Read the extracted text below: hidden terms often sit in micro-print."});
 if(off)F.push({k:"pdf_offpage",sev:3,t:`${off} pieces of text sit outside the visible page area`,q:"Text outside the page is invisible when viewed but is part of the document."});
 const maxF=Math.max(0,...fontsPer);if(maxF>=9)F.push({k:"pdf_fonts",sev:1,t:`Up to ${maxF} different fonts on one page`,q:"On statements and paystubs, mixed fonts in the numbers can mean edited figures."});
 if(scanned.length)F.push({k:"pdf_scan",sev:1,t:`${scanned.length} page(s) have no text layer (scanned image): ${scanned.slice(0,12).join(", ")}`,q:"Use Deep screen: those pages go to Claude as images."});
 return{text:pages.map((t,i)=>`[Page ${i+1}]\n${t}`).join("\n\n"),pages:pdf.numPages,scanned,pdf,forensic:F,meta:{Title:info.Title,Author:info.Author,Creator:info.Creator,Producer:info.Producer,Created:dsPdfDate(cd),Modified:dsPdfDate(md),Saves:eof}}}
const dsPdfDate=s=>{const m=String(s||"").match(/D:(\d{4})(\d{2})?(\d{2})?(\d{2})?(\d{2})?/);return m?`${m[1]}-${m[2]||"01"}-${m[3]||"01"}${m[4]?" "+m[4]+":"+(m[5]||"00"):""}`:String(s||"")};
async function dsPdfImages(d,max){if(!d.pdf||!d.scanned.length)return[];const out=[];for(const p of d.scanned.slice(0,max)){const pg=await d.pdf.getPage(p);const vp=pg.getViewport({scale:1.6});const c=document.createElement("canvas");c.width=vp.width;c.height=vp.height;await pg.render({canvasContext:c.getContext("2d"),viewport:vp}).promise;out.push(await new Promise(r=>c.toBlob(r,"image/jpeg",0.82)))}return out}
async function dsReadDocx(buf){const Z=await dsZipLib();const z=await Z.loadAsync(buf);const F=[];const rd=async n=>z.file(n)?z.file(n).async("string"):"";
 const xml=await rd("word/document.xml");const names=Object.keys(z.files);const hdr=(await Promise.all(names.filter(n=>/^word\/(header|footer)\d*\.xml$/.test(n)).map(rd))).join("");
 const fn=(await rd("word/footnotes.xml"))+(await rd("word/endnotes.xml"));
 const runs=(x)=>{let hidden=[],white=[],small=[],ins=[],del=[];x.replace(/<w:ins\b[\s\S]*?<\/w:ins>/g,m=>{ins.push(dsWText(m));return m});x.replace(/<w:del\b[\s\S]*?<\/w:del>/g,m=>{del.push(dsWText(m.replace(/w:delText/g,"w:t")));return m});
  x.replace(/<w:r\b[^>]*>([\s\S]*?)<\/w:r>/g,(m,inner)=>{const pr=(inner.match(/<w:rPr>[\s\S]*?<\/w:rPr>/)||[""])[0];const t=dsWText(inner);if(!t.trim())return m;if(/<w:vanish\/>|<w:vanish w:val="(1|true)"\/>|<w:specVanish/.test(pr))hidden.push(t);const c=(pr.match(/<w:color w:val="([0-9A-Fa-f]{6})"/)||[])[1];if(c&&/^(FFFFFF|FEFEFE|FDFDFD|FCFCFC|FAFAFA|F[0-9A-F]F[0-9A-F]F[0-9A-F])$/i.test(c)&&!/<w:shd [^>]*w:fill="(?!auto|FFFFFF)[0-9A-F]{6}"/i.test(pr+inner))white.push(t);const sz=+((pr.match(/<w:sz w:val="(\d+)"/)||[])[1]||0);if(sz&&sz<=8)small.push(t);return m});return{hidden,white,small,ins,del}};
 const R=runs(xml+hdr);
 if(R.hidden.length)F.push({k:"docx_hidden",sev:3,t:`${R.hidden.length} run(s) of HIDDEN text (Word "hidden" formatting — invisible on screen and in print)`,q:R.hidden.join(" | ").slice(0,400)});
 if(R.white.length)F.push({k:"docx_white",sev:3,t:`${R.white.length} run(s) of white-on-white text`,q:R.white.join(" | ").slice(0,400)});
 if(R.small.length)F.push({k:"docx_small",sev:2,t:`${R.small.length} run(s) of micro text (4 pt or smaller)`,q:R.small.join(" | ").slice(0,400)});
 if(R.ins.length||R.del.length)F.push({k:"docx_track",sev:3,t:`Tracked changes still in the file: ${R.ins.length} insertion(s), ${R.del.length} deletion(s)`,q:`Inserted: ${R.ins.join(" | ").slice(0,250)}${R.del.length?` — Deleted: ${R.del.join(" | ").slice(0,250)}`:""}`});
 const cm=await rd("word/comments.xml");const cms=[...cm.matchAll(/<w:comment\b[^>]*w:author="([^"]*)"[^>]*>([\s\S]*?)<\/w:comment>/g)].map(m=>`${m[1]}: ${dsWText(m[2])}`);if(cms.length)F.push({k:"docx_comments",sev:2,t:`${cms.length} reviewer comment(s) left in the file`,q:cms.join(" | ").slice(0,500)});
 if(names.some(n=>/vbaProject\.bin$/i.test(n)))F.push({k:"docx_macro",sev:3,t:"Contains macros (vbaProject.bin)",q:"Do not enable content; request a clean .docx or PDF."});
 if(names.some(n=>/^word\/embeddings\//.test(n)))F.push({k:"docx_embed",sev:2,t:`Embedded objects: ${names.filter(n=>/^word\/embeddings\//.test(n)).map(n=>n.split("/").pop()).join(", ").slice(0,160)}`,q:"Embedded spreadsheets or files can hold terms not shown on the page."});
 const rels=await rd("word/_rels/document.xml.rels");const ext=[...rels.matchAll(/Target="([^"]+)"[^>]*TargetMode="External"/g)].map(m=>m[1]).filter(u=>!/^mailto:/.test(u));if(ext.length)F.push({k:"docx_ext",sev:ext.some(u=>/attachedTemplate|\.dotm|\\\\|file:/i.test(u))?3:1,t:`${ext.length} external link(s)/reference(s)`,q:ext.slice(0,6).join(" | ").slice(0,300)});
 if(/<w:fldSimple[^>]*INCLUDETEXT|INCLUDETEXT|DDEAUTO/i.test(xml))F.push({k:"docx_field",sev:3,t:"Field codes pull text from outside the document (INCLUDETEXT / DDE)",q:""});
 const core=await rd("docProps/core.xml");const g=t=>((core.match(new RegExp(`<${t}[^>]*>([^<]*)</${t}>`))||[])[1]||"");const app=await rd("docProps/app.xml");
 const meta={Author:g("dc:creator"),"Last modified by":g("cp:lastModifiedBy"),Revision:g("cp:revision"),Created:g("dcterms:created"),Modified:g("dcterms:modified"),Template:((app.match(/<Template>([^<]*)/)||[])[1]||""),Company:((app.match(/<Company>([^<]*)/)||[])[1]||"")};
 if(meta.Author&&meta["Last modified by"]&&meta.Author!==meta["Last modified by"])F.push({k:"docx_authors",sev:1,t:`Written by "${meta.Author}", last edited by "${meta["Last modified by"]}"`,q:"Ask who changed it after the version you agreed."});
 const body=dsWParas(xml);const text=[dsWParas(hdr)&&"[Headers/footers]\n"+dsWParas(hdr),body,fn.trim()&&"[Footnotes]\n"+dsWParas(fn),R.del.length&&"[Deleted (tracked) text]\n"+R.del.join("\n"),R.hidden.length&&"[Hidden text]\n"+R.hidden.join("\n"),cms.length&&"[Comments]\n"+cms.join("\n")].filter(Boolean).join("\n\n");
 return{text,forensic:F,meta,pages:0,scanned:[]}}
const dsWText=x=>(x.match(/<w:t\b[^>]*>[^<]*<\/w:t>|<w:tab\/>|<w:br\/>/g)||[]).map(t=>t==="<w:tab/>"?"\t":t==="<w:br/>"?"\n":t.replace(/<[^>]+>/g,"")).join("").replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&quot;/g,'"').replace(/&apos;/g,"'");
const dsWParas=x=>(x.match(/<w:p\b[\s\S]*?<\/w:p>/g)||[]).map(p=>dsWText(p.replace(/<w:del\b[\s\S]*?<\/w:del>/g,""))).join("\n").replace(/\n{3,}/g,"\n\n").trim();
async function dsReadFile(file){const nm=file.name,lc=nm.toLowerCase(),buf=await file.arrayBuffer();const base={name:nm,size:file.size,kind:"text",forensic:[],meta:{},pages:0,scanned:[],images:[]};
 if(/\.pdf$/.test(lc)||file.type==="application/pdf")return Object.assign(base,{kind:"pdf"},await dsReadPdf(file,buf));
 if(/\.docx$/.test(lc))return Object.assign(base,{kind:"docx"},await dsReadDocx(buf));
 if(/\.(png|jpe?g|gif|webp|heic)$/.test(lc)||/^image\//.test(file.type))return Object.assign(base,{kind:"image",text:"",images:[file],forensic:[{k:"img",sev:1,t:"Image/photo: no text layer — Deep screen reads it as an image",q:""}]});
 if(/\.doc$/.test(lc))return Object.assign(base,{kind:"doc",text:dsLatin1(new Uint8Array(buf)).replace(/[^\x20-\x7E\n\r\t]+/g," ").replace(/ {3,}/g," "),forensic:[{k:"doc_old",sev:2,t:"Old binary Word (.doc): text recovered roughly; hidden/tracked content can't be checked",q:"Ask for .docx or PDF for a full forensic check."}]});
 let t=new TextDecoder().decode(buf);if(/\.(html?|eml|mht)$/.test(lc)){const hid=(t.match(/display\s*:\s*none|visibility\s*:\s*hidden|font-size\s*:\s*[01](px|pt)|color\s*:\s*#?fff(fff)?\b/gi)||[]).length;if(hid)base.forensic.push({k:"html_hidden",sev:3,t:`${hid} hidden-text style(s) (display:none, white or 0-1px text)`,q:"Common in phishing and in emails hiding terms."});t=t.replace(/<style[\s\S]*?<\/style>|<script[\s\S]*?<\/script>/gi," ").replace(/<br\s*\/?>|<\/(p|div|tr|li|h\d)>/gi,"\n").replace(/<[^>]+>/g," ").replace(/&nbsp;/g," ").replace(/&amp;/g,"&").replace(/[ \t]{2,}/g," ")}
 if(/\.rtf$/.test(lc))t=t.replace(/\\par[d]?/g,"\n").replace(/\{\\\*[^}]*\}|\\[a-z]+-?\d* ?|[{}]/g,"");
 return Object.assign(base,{text:t})}
