const dsRiskTag=r=>r>=60?`<span class="tag" style="background:#b42318;color:#fff">High ${r}</span>`:r>=30?`<span class="tag" style="background:#b54708;color:#fff">Elevated ${r}</span>`:`<span class="tag" style="background:#067647;color:#fff">Low ${r}</span>`;
const dsSev=n=>n===3?"🔴":n===2?"🟠":"🟢";
async function dsIngest(files){const out=[];for(const f of files){const st=$("#ds_st");if(st)st.textContent=`Reading ${f.name}…`;try{const d=await dsReadFile(f);d.type=dsType(d.text||"");d.scan=dsScan(d.text||"");d.ts=Date.now();d.id="ds"+d.ts+Math.floor(Math.random()*999);d.risk=dsRisk(d);out.push(d)}catch(e){toast(`${f.name}: ${String(e.message||e).slice(0,140)}`)}}
 DS_S.docs.push(...out);if(out.length){DS_S.cur=DS_S.docs.length-out.length;out.forEach(dsHist)}const st=$("#ds_st");if(st)st.textContent=out.length?`${out.length} document(s) screened.`:"";return out}
function dsFromText(name,text){const d={name,size:text.length,kind:"text",text,forensic:[],meta:{},pages:0,scanned:[],images:[]};d.type=dsType(text);d.scan=dsScan(text);d.ts=Date.now();d.id="ds"+d.ts;d.risk=dsRisk(d);DS_S.docs.push(d);DS_S.cur=DS_S.docs.length-1;dsHist(d);return d}
function dsHist(d){const H=store.get("ds_hist",[]).filter(h=>h.id!==d.id);H.unshift({id:d.id,name:d.name,type:d.type.n,ts:d.ts,risk:d.risk,words:d.scan.words,flags:d.scan.hits.filter(h=>h.sev===3).map(h=>h.n).slice(0,8),forensic:(d.forensic||[]).filter(f=>f.sev===3).map(f=>f.t).slice(0,5),summary:d.ai?d.ai.summary:"",next:d.ai?(d.ai.deadlines||[]).slice(0,5).map(x=>`${x.date||""} ${x.what||""}`):[]});store.set("ds_hist",H.slice(0,60))}
/* ---------------- Claude deep screen ---------------- */
const DS_CHUNK=60000;
const dsChunks=t=>{const out=[];let i=0;while(i<t.length){let j=Math.min(t.length,i+DS_CHUNK);if(j<t.length){const k=t.lastIndexOf("\n",j);if(k>i+DS_CHUNK*0.6)j=k}out.push(t.slice(i,j));i=j}return out.length?out:[""]};
const DS_JSON_CHUNK=`{"doc_type":string,"summary":string,"parties":[{"role":string,"name":string}],"key_terms":[{"term":string,"value":string,"quote":string}],"dates":[{"date":"YYYY-MM-DD or as written","what":string,"quote":string}],"deadlines":[{"date":"YYYY-MM-DD or relative e.g. '17 days after acceptance'","what":string,"who":string,"consequence":string,"quote":string}],"money":[{"amount":string,"what":string,"who_pays":string}],"clauses":[{"name":string,"category":string,"severity":"high|medium|low","quote":string,"plain_english":string,"who_it_favors":string,"action":string}],"obligations":[{"party":string,"must":string,"by":string}],"hidden_or_unusual":[{"what":string,"quote":string,"why":string}],"inconsistencies":[{"what":string,"quote":string}],"missing":[string],"questions":[string]}`;
function dsChunkPrompt(d,chunk,i,n){return`You are a forensic document reviewer for Steven Shearrill, a California real estate broker and mortgage broker (licensed CA, IL, NV, FL, AZ). Screen this document with a fine-tooth comb. Nothing may be skipped: every date, every deadline or time period (with what starts the clock and what happens if it's missed), every amount, every clause that shifts risk, waives a right, renews automatically, adds a fee, creates a penalty, or is unusual for this kind of document. Look specifically for anything hidden: fine print, terms buried in definitions or exhibits, cross-references that change meaning, numbers that don't match each other, blanks, and language that conflicts with a typical ${d.type.n}. Quote the exact words (max 30 words per quote). If the text includes "[Hidden text]", "[Deleted (tracked) text]" or "[Comments]" sections, those were NOT visible in the document: treat them as hidden content and report them. Do not invent anything not in the text; if unsure, say so in "questions". This is part ${i+1} of ${n} of "${d.name}" (detected type: ${d.type.n}). Today is ${new Date().toISOString().slice(0,10)}.${d.anchor?` Anchor date (acceptance / start) given by Steven: ${d.anchor}.`:""}
Reply with only JSON in this shape: ${DS_JSON_CHUNK}
--- DOCUMENT TEXT ---
${chunk}`}
function dsSynthPrompt(d,parts,rules){return`You are a forensic document reviewer for Steven Shearrill (California real estate broker and mortgage broker/MLO, Patriot Pacific Financial). Below are findings from ${parts.length} part(s) of "${d.name}" (detected type: ${d.type.n}), plus findings from the in-browser scanner (rules and file forensics). Merge them into one final screening. De-duplicate; keep exact quotes; resolve relative deadlines into calendar dates when an anchor date is known${d.anchor?` (anchor: ${d.anchor})`:""}; sort the timeline by date. Score overall risk 0-100 for Steven's side (or his client's side) and say who the document favors. Write the client summary at an 8th-grade level, no legal advice, suggest review by an attorney where appropriate. Never recommend a lender or product because it pays more.
Reply with only JSON: {"title":string,"doc_type":string,"risk":number,"verdict":string,"favors":string,"summary":string,"client_summary":string,"key_terms":[{"term":string,"value":string}],"timeline":[{"date":string,"what":string,"who":string,"consequence":string,"quote":string}],"deadlines":[{"date":string,"what":string,"who":string}],"red_flags":[{"severity":"high|medium|low","what":string,"quote":string,"why":string,"action":string}],"hidden":[{"what":string,"quote":string,"why":string}],"clauses":[{"name":string,"category":string,"severity":"high|medium|low","plain_english":string,"who_it_favors":string,"action":string,"quote":string}],"obligations":[{"party":string,"must":string,"by":string}],"money":[{"amount":string,"what":string,"who_pays":string}],"inconsistencies":[string],"missing":[string],"negotiation_points":[string],"questions":[string],"next_steps":[string]}
--- PART FINDINGS ---
${JSON.stringify(parts).slice(0,170000)}
--- IN-BROWSER SCANNER ---
${JSON.stringify(rules).slice(0,40000)}`}
const dsRuleDigest=d=>({forensic:(d.forensic||[]).concat(d.scan.odd).map(f=>({sev:f.sev,t:f.t,q:f.q})),rules:d.scan.hits.map(h=>({n:h.n,sev:h.sev,quote:h.ms[0].ctx.slice(0,220)})),blanks:d.scan.blanks.length,big_deposits:d.scan.bigDep.slice(0,15),relative_deadlines:d.scan.rel.slice(0,40).map(r=>({raw:r.raw,due:r.due?r.due.toISOString().slice(0,10):""})),meta:d.meta});
async function dsDeep(d,prog){const s=await pbSampleFn();if(!s)throw{code:"not_granted"};const opt=dsOpt();d.anchor=opt.anchor;const tier=opt.deep||"default";const txt=opt.mask?dsMask(d.text||""):(d.text||"");
 const lim=await s.limits().catch(()=>null);const canImg=!!(lim&&lim.images);const maxImg=canImg?Math.min(lim.images.maxCount||5,8):0;let imgs=[];
 if(canImg){imgs=d.images&&d.images.length?d.images.slice(0,maxImg):[];if(d.kind==="pdf"&&d.scanned.length){prog(`Rendering ${Math.min(d.scanned.length,maxImg)} scanned page(s)…`);imgs=imgs.concat(await dsPdfImages(d,maxImg-imgs.length))}}
 else if(d.kind==="image")throw{code:"images_unavailable",message:"This view can't send images to Claude."};
 const parts=[];const ch=txt.trim()?dsChunks(txt):[];const n=ch.length+(imgs.length?1:0);
 for(let i=0;i<ch.length;i++){prog(`Deep screen part ${i+1} of ${n}…`);DS_S.ctl=new AbortController();parts.push(await s.json(dsChunkPrompt(d,ch[i],i,n),{modelTier:tier,signal:DS_S.ctl.signal}))}
 if(imgs.length){prog(`Reading ${imgs.length} page image(s)…`);DS_S.ctl=new AbortController();parts.push(await s.json(dsChunkPrompt(d,"(The document content is in the attached images: scanned pages or photos. Read every word, including stamps, handwriting, initials and fine print. Report any SSN or account number only as last 4.)",ch.length,n),{modelTier:tier,images:imgs,signal:DS_S.ctl.signal}))}
 prog("Synthesizing the final screening…");DS_S.ctl=new AbortController();const fin=await s.json(dsSynthPrompt(d,parts,dsRuleDigest(d)),{modelTier:tier==="quick"?"default":tier,signal:DS_S.ctl.signal});
 d.ai=fin;d.aiParts=parts;d.risk=dsRisk(d);dsHist(d);if(typeof pbLog==="function")pbLog("Doc Screener",1,`${d.name}: risk ${d.risk}`);return fin}
/* ---------------- rendering ---------------- */
const dsL=(a,f)=>(a&&a.length)?`<ul class="sm" style="margin:4px 0 0 18px">${a.map(x=>`<li style="margin:3px 0">${f?f(x):esc(String(x))}</li>`).join("")}</ul>`:'<span class="mut sm">None found.</span>';
const dsQ=q=>q?`<div class="mut sm" style="border-left:3px solid var(--line);padding-left:8px;margin-top:2px">“${esc(String(q).slice(0,400))}”</div>`:"";
const dsSevW=s=>/high/i.test(s)?3:/med/i.test(s)?2:1;
function dsTimeline(d){const now=new Date();now.setHours(0,0,0,0);const T=[];d.scan.dates.forEach(x=>T.push({d:x.d,lab:x.raw,what:x.ctx,src:"text"}));d.scan.rel.forEach(x=>{if(x.due)T.push({d:x.due,lab:`${x.raw.split(/\s+/).slice(0,5).join(" ")} → ${x.due.toLocaleDateString()}`,what:x.ctx,src:"relative"})});
 if(d.ai)(d.ai.timeline||[]).concat(d.ai.deadlines||[]).forEach(x=>{const dd=dsParseDate(String(x.date||""))||(/^\d{4}-\d{2}-\d{2}/.test(x.date||"")?new Date(String(x.date).slice(0,10)+"T12:00:00"):null);T.push({d:dd,lab:String(x.date||""),what:`${x.what||""}${x.who?` — ${x.who}`:""}${x.consequence?` (if missed: ${x.consequence})`:""}`,src:"Claude",q:x.quote})});
 const seen=new Set();return T.filter(x=>{const k=(x.d?x.d.toDateString():x.lab)+"|"+String(x.what).slice(0,40);if(seen.has(k))return false;seen.add(k);return true}).sort((a,b)=>(a.d?+a.d:9e15)-(b.d?+b.d:9e15)).map(x=>Object.assign(x,{days:x.d?Math.round((x.d-now)/864e5):null}))}
function dsOverview(d){const s=d.scan,ai=d.ai;const hi=s.hits.filter(h=>h.sev===3).length;const fz=(d.forensic||[]).concat(s.odd);
 return`<div class="grid g2" style="align-items:start"><div class="card"><div class="row" style="flex-wrap:wrap;gap:6px"><b class="sp">${esc(d.name)}</b>${dsRiskTag(d.risk)}</div><div class="sm mut" style="margin-top:4px">${esc(d.type.n)} · ${d.kind.toUpperCase()}${d.pages?` · ${d.pages} pages`:""} · ${s.words.toLocaleString()} words (~${s.read} min read) · ${s.dates.length} dates · ${s.rel.length} time periods · ${s.money.length} amounts · ${s.hits.length} clause types (${hi} high) · ${fz.length} forensic notes · ${s.blanks.length} blanks</div>
 ${ai?`<div style="margin-top:8px"><b>Verdict:</b> ${esc(ai.verdict||"")} ${ai.favors?`<span class="tag">Favors: ${esc(ai.favors)}</span>`:""}<p class="sm" style="margin:6px 0">${esc(ai.summary||"")}</p><details class="acc"><summary>Client-friendly summary</summary><p class="sm">${esc(ai.client_summary||"")}</p><button class="btn ghost sm" id="ds_cpcl">Copy</button></details></div>`:`<p class="sm mut" style="margin-top:8px">Instant scan done in your browser. Press <b>Deep screen with Claude</b> for the clause-by-clause read, summaries, timeline with consequences, hidden terms and negotiation points.</p>`}</div>
 <div class="card"><b>What to verify for a ${esc(d.type.n)}</b>${dsL(d.type.chk)}${Object.values(d.meta||{}).some(Boolean)?`<details class="acc" style="margin-top:6px"><summary>File properties</summary><table class="sm">${Object.entries(d.meta).filter(e=>e[1]).map(e=>`<tr><td class="mut">${esc(e[0])}</td><td>${esc(String(e[1]))}</td></tr>`).join("")}</table></details>`:""}</div></div>
 ${ai&&(ai.red_flags||[]).length?`<div class="card" style="border-left:4px solid #b42318"><b>Red flags</b>${dsL(ai.red_flags,x=>`${dsSev(dsSevW(x.severity))} <b>${esc(x.what)}</b> — ${esc(x.why||"")} <i>${esc(x.action||"")}</i>${dsQ(x.quote)}`)}</div>`:""}
 <div class="card"><b>Forensics: hidden or altered content</b> <span class="sm mut">(file structure checks — they run in your browser)</span>${dsL(fz.sort((a,b)=>b.sev-a.sev),f=>`${dsSev(f.sev)} ${esc(f.t)}${f.q?`<div class="mut sm">${esc(f.q)}</div>`:""}`)}${ai&&(ai.hidden||[]).length?`<b class="sm">Hidden or unusual terms (Claude)</b>${dsL(ai.hidden,x=>`<b>${esc(x.what)}</b> — ${esc(x.why||"")}${dsQ(x.quote)}`)}`:""}</div>
 ${ai?`<div class="grid g2" style="align-items:start"><div class="card"><b>Key terms</b><table class="sm">${(ai.key_terms||[]).map(k=>`<tr><td class="mut">${esc(k.term)}</td><td>${esc(k.value)}</td></tr>`).join("")}</table></div><div class="card"><b>Money</b>${dsL(ai.money,x=>`<b>${esc(x.amount)}</b> ${esc(x.what)}${x.who_pays?` <span class="mut">(${esc(x.who_pays)})</span>`:""}`)}</div></div>
 <div class="grid g2" style="align-items:start"><div class="card"><b>Negotiation points</b>${dsL(ai.negotiation_points)}<b class="sm">Questions to ask</b>${dsL(ai.questions)}</div><div class="card"><b>Missing / inconsistent</b>${dsL((ai.missing||[]).concat(ai.inconsistencies||[]))}<b class="sm">Next steps</b>${dsL(ai.next_steps)}</div></div>`:""}`}
function dsTimeHtml(d){const T=dsTimeline(d);return`<div class="card"><div class="row" style="flex-wrap:wrap;gap:6px"><b class="sp">Timeline & deadlines (${T.length})</b><label class="sm">Anchor date (acceptance / start) <input type="date" id="ds_anchor" value="${esc(dsOpt().anchor)}" style="width:auto"></label><button class="btn ghost sm" id="ds_ics">Download .ics</button><button class="btn ghost sm" id="ds_csv">CSV</button><button class="btn ghost sm" id="ds_tb">Upcoming → Board</button></div><p class="sm mut" style="margin:4px 0">Relative periods ("within 17 days") become dates from the anchor date: calendar days by default; business/banking days skip weekends and federal holidays. Always confirm against the contract's own definition of "days".</p>
 <table class="sm"><thead><tr><th>Date</th><th>In</th><th>What</th><th>Source</th></tr></thead><tbody>${T.map(x=>`<tr${x.days!=null&&x.days>=0&&x.days<=7?' style="background:rgba(181,71,8,.12)"':""}><td style="white-space:nowrap"><b>${x.d?x.d.toLocaleDateString():esc(x.lab)}</b></td><td style="white-space:nowrap">${x.days==null?"—":x.days<0?`<span class="mut">${-x.days}d ago</span>`:x.days===0?"<b>today</b>":`${x.days}d`}</td><td>${esc(String(x.what).slice(0,300))}${dsQ(x.q)}</td><td class="mut">${x.src}</td></tr>`).join("")||'<tr><td colspan="4" class="mut">No dates found.</td></tr>'}</tbody></table>
 <details class="acc" style="margin-top:6px"><summary>All time periods found (${d.scan.rel.length})</summary>${dsL(d.scan.rel,r=>`<b>${esc(r.raw)}</b>${r.due?` → <b>${r.due.toLocaleDateString()}</b>`:""} <span class="mut">${esc(r.ctx)}</span>`)}</details></div>`}
function dsClauseHtml(d){const cat=store.get("ds_cat","");const H=d.scan.hits.filter(h=>!cat||h.cat===cat).sort((a,b)=>b.sev-a.sev);const ai=d.ai;
 return`<div class="card"><div class="row" style="flex-wrap:wrap;gap:6px"><b class="sp">Clauses & risk rules (${d.scan.hits.length} of ${DS_RULES.length} rule types matched)</b><select id="ds_cat" style="width:auto"><option value="">All categories</option>${DS_CATS.map(c=>`<option${c===cat?" selected":""}>${esc(c)}</option>`).join("")}</select></div>
 ${H.map(h=>`<details class="acc"><summary>${dsSev(h.sev)} <b>${esc(h.n)}</b> <span class="mut sm">${esc(h.cat)} · ${h.ms.length}×</span></summary><div class="sm"><b>Why:</b> ${esc(h.why)}<br><b>Do:</b> ${esc(h.act)}</div>${h.ms.map(m=>`<div class="mut sm ds-jump" data-i="${m.i}" style="border-left:3px solid var(--line);padding-left:8px;margin-top:4px;cursor:pointer">${esc(m.ctx)}</div>`).join("")}</details>`).join("")||'<p class="mut sm">No rule matched in this category.</p>'}</div>
 ${ai&&(ai.clauses||[]).length?`<div class="card"><b>Clause-by-clause (Claude)</b>${(ai.clauses||[]).sort((a,b)=>dsSevW(b.severity)-dsSevW(a.severity)).map(c=>`<details class="acc"><summary>${dsSev(dsSevW(c.severity))} <b>${esc(c.name)}</b> <span class="mut sm">${esc(c.category||"")}${c.who_it_favors?` · favors ${esc(c.who_it_favors)}`:""}</span></summary><div class="sm">${esc(c.plain_english||"")}<br><b>Do:</b> ${esc(c.action||"")}</div>${dsQ(c.quote)}</details>`).join("")}</div><div class="card"><b>Obligations by party</b><table class="sm">${(ai.obligations||[]).map(o=>`<tr><td><b>${esc(o.party)}</b></td><td>${esc(o.must)}</td><td class="mut">${esc(o.by||"")}</td></tr>`).join("")}</table></div>`:""}`}
function dsDataHtml(d){const s=d.scan;return`<div class="grid g2" style="align-items:start"><div class="card"><b>Parties</b>${dsL(s.parties.concat(d.ai?(d.ai.parties||[]):[]).filter((p,i,a)=>a.findIndex(q=>q.name===p.name)===i),p=>`<b>${esc(p.role)}</b>: ${esc(p.name)}`)}<b class="sm">Blanks / placeholders (${s.blanks.length})</b>${dsL(s.blanks.slice(0,25),b=>`<code>${esc(b.raw)}</code> <span class="mut">${esc(b.ctx)}</span>`)}</div>
 <div class="card"><b>Amounts (${s.money.length})</b><div style="max-height:260px;overflow:auto">${dsL(s.money.slice(0,120),m=>`<b>${esc(m.raw)}</b> <span class="mut">${esc(m.ctx)}</span>`)}</div><b class="sm">Percentages (${s.pct.length})</b><div style="max-height:180px;overflow:auto">${dsL(s.pct.slice(0,80),m=>`<b>${esc(m.raw)}</b> <span class="mut">${esc(m.ctx)}</span>`)}</div></div></div>
 <div class="card"><div class="row" style="gap:6px;flex-wrap:wrap"><b class="sp">Large deposits / credits (≥ $${(+dsOpt().big).toLocaleString()})</b><label class="sm">Threshold $<input id="ds_big" type="number" value="${esc(dsOpt().big)}" style="width:100px"></label></div>${dsL(s.bigDep,x=>`<b>$${Math.round(x.v).toLocaleString()}</b> <span class="mut">${esc(x.line)}</span>`)}<p class="sm mut">Agency guides generally require sourcing large deposits (Fannie Mae: over 50% of monthly qualifying income for purchases). Verify the current guide.</p></div>`}
function dsReaderHtml(d){const t=d.text||"";if(!t)return'<div class="card mut">No text layer (image or scan). Use Deep screen to read it as an image.</div>';const marks=[];d.scan.hits.forEach(h=>h.ms.forEach(m=>marks.push([m.i,m.len,h.sev,h.n])));d.scan.dates.forEach(x=>marks.push([x.i,x.raw.length,0,"date"]));d.scan.rel.forEach(x=>marks.push([x.i,x.raw.length,0,"period"]));d.scan.blanks.forEach(x=>marks.push([x.i,x.raw.length,4,"blank"]));
 marks.sort((a,b)=>a[0]-b[0]);let out="",p=0;const col={0:"rgba(46,144,250,.25)",1:"rgba(18,183,106,.25)",2:"rgba(247,144,9,.3)",3:"rgba(240,68,56,.32)",4:"rgba(122,90,248,.3)"};marks.forEach(m=>{if(m[0]<p)return;out+=esc(t.slice(p,m[0]))+`<mark id="dsm${m[0]}" title="${esc(m[3])}" style="background:${col[m[2]]};color:inherit">${esc(t.slice(m[0],m[0]+m[1]))}</mark>`;p=m[0]+m[1]});out+=esc(t.slice(p));
 return`<div class="card"><div class="row" style="gap:6px;flex-wrap:wrap"><input id="ds_find" placeholder="Find in document…" style="flex:1;min-width:200px"><span class="sm mut" id="ds_fc"></span></div><p class="sm mut" style="margin:4px 0"><mark style="background:${col[3]}">high-risk</mark> <mark style="background:${col[2]}">medium</mark> <mark style="background:${col[1]}">low</mark> <mark style="background:${col[0]}">date / time period</mark> <mark style="background:${col[4]}">blank</mark></p><div id="ds_txt" class="sm" style="white-space:pre-wrap;max-height:620px;overflow:auto;border:1px solid var(--line);padding:10px;border-radius:8px;font-family:ui-monospace,monospace;font-size:12px">${out}</div></div>`}
function dsAskHtml(){return`<div class="card"><b>Ask the document</b> <span class="sm mut">Claude answers only from this document and quotes it.</span><div id="ds_chat" class="sm" style="margin:8px 0;max-height:420px;overflow:auto">${DS_S.chat.map(m=>`<div style="margin:6px 0"><b>${m.role==="user"?"You":"VANESSA"}:</b> ${esc(m.content).replace(/\n/g,"<br>")}</div>`).join("")}</div><div class="row" style="gap:6px"><input id="ds_q" placeholder="e.g. When does the inspection contingency end? Who pays the HOA transfer fee? Is there anything that renews automatically?" style="flex:1"><button class="btn sm" id="ds_ask">Ask</button><button class="btn ghost sm" id="ds_stop2">Stop</button></div><div class="row" style="gap:4px;flex-wrap:wrap;margin-top:6px">${["List every deadline and what happens if it is missed","What could cost my client money that isn't obvious?","What rights does my client give up?","Summarize in 5 bullets for the client","Draft a counter / addendum asking to fix the top 3 issues","What should the lender or underwriter flag here?"].map(q=>`<button class="btn ghost sm ds-pre">${esc(q)}</button>`).join("")}</div></div>`}
function dsCmpHtml(){const D=DS_S.docs;return`<div class="card"><b>Compare two documents</b> <span class="sm mut">e.g. LE vs CD, contract vs counter offer, draft vs signed, last year's agreement vs this year's.</span><div class="row" style="gap:6px;margin-top:6px;flex-wrap:wrap"><select id="ds_ca" style="width:auto">${D.map((d,i)=>`<option value="${i}">${esc(d.name)}</option>`).join("")}</select> vs <select id="ds_cb" style="width:auto">${D.map((d,i)=>`<option value="${i}"${i===D.length-1?" selected":""}>${esc(d.name)}</option>`).join("")}</select><button class="btn sm" id="ds_cmp">Compare</button><button class="btn ghost sm" id="ds_cmpai">What changed & who it favors (Claude)</button></div><div id="ds_cmpout" class="sm" style="margin-top:8px"></div></div>`}
function dsDiff(a,b){const A=a.split(/\n+/).map(s=>s.trim()).filter(Boolean),B=b.split(/\n+/).map(s=>s.trim()).filter(Boolean);if(A.length*B.length>4e6)return null;const n=A.length,m=B.length;const L=Array.from({length:n+1},()=>new Uint16Array(m+1));for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)L[i][j]=A[i]===B[j]?L[i+1][j+1]+1:Math.max(L[i+1][j],L[i][j+1]);const out=[];let i=0,j=0;while(i<n&&j<m){if(A[i]===B[j]){i++;j++}else if(L[i+1][j]>=L[i][j+1])out.push(["-",A[i++]]);else out.push(["+",B[j++]])}while(i<n)out.push(["-",A[i++]]);while(j<m)out.push(["+",B[j++]]);return out}
function dsHistHtml(){const H=store.get("ds_hist",[]);return`<div class="card"><div class="row"><b class="sp">Screening history (${H.length})</b><button class="btn ghost sm" id="ds_hcsv">Export CSV</button><button class="btn ghost sm" id="ds_hclr">Clear</button></div><p class="sm mut">Only the results are kept in this browser (no document text). Re-upload a file to see it again.</p><table class="sm"><thead><tr><th>When</th><th>Document</th><th>Type</th><th>Risk</th><th>High flags</th></tr></thead><tbody>${H.map(h=>`<tr><td>${new Date(h.ts).toLocaleString()}</td><td><b>${esc(h.name)}</b>${h.summary?`<div class="mut">${esc(h.summary.slice(0,200))}</div>`:""}</td><td>${esc(h.type)}</td><td>${dsRiskTag(h.risk)}</td><td class="mut">${esc(h.flags.concat(h.forensic).join(", ").slice(0,200))}</td></tr>`).join("")}</tbody></table></div>`}
function dsGuideHtml(){return`<div class="card"><b>How the screener works</b>${omList(["Drop in PDFs, Word .docx, photos/scans (JPG/PNG), text, .eml/.html emails or paste text. Batch uploads screen each file.","Instant layer (your browser, nothing leaves the page): document type, every date, every time period turned into a calendar date from your anchor date, amounts, percentages, parties, blanks, "+DS_RULES.length+" risk rules in "+DS_CATS.length+" categories, and file forensics.","Forensics look for what a reader can't see: Word hidden/white/micro text, tracked changes and deletions, reviewer comments, macros, external links and INCLUDETEXT fields; PDF JavaScript, auto-actions, embedded files, fillable fields, edits after creation (multiple saves), editing-tool producers, micro and off-page text, mixed fonts; zero-width, right-to-left override and look-alike letters; changed wire instructions.","Deep screen (Claude, on your click): the full text is split into ~60k-character parts, each read clause by clause; scanned pages and photos go as images; then a synthesis gives the verdict, risk score, who it favors, executive and client summaries, timeline with consequences, red flags, hidden terms, obligations, money, missing items, negotiation points, questions and next steps.","Privacy: 'Mask SSNs and account numbers' is on by default before anything goes to Claude. Results history keeps only the findings. Treat borrower files under the GLBA Safeguards Rule.","Exports: Word report, .ics deadlines for your calendar, CSV timeline, Handoff Board cards, Gmail draft of the summary to yourself (draft only).","Limits: this is a screening aid, not legal advice. Contract interpretation goes to an attorney; loan rules must be checked against the current guide and the lender. Word .doc (old format), protected PDFs and handwriting reduce accuracy."])}</div><div class="card"><b>Rule library (${DS_RULES.length})</b>${DS_CATS.map(c=>`<details class="acc"><summary><b>${esc(c)}</b> <span class="mut sm">${DS_RULES.filter(r=>r[2]===c).length}</span></summary>${dsL(DS_RULES.filter(r=>r[2]===c),r=>`${dsSev(r[3])} <b>${esc(r[1])}</b> — ${esc(r[5])} <i>${esc(r[6])}</i>`)}</details>`).join("")}</div>`}
