async function dsSaveBlob(filename,blob){try{const dl=window.claude&&window.claude.use?await window.claude.use("downloads"):null;if(dl){await dl.save({filename,data:blob});toast("Saved "+filename);return}}catch(e){if(e&&e.code==="declined")return toast("Download cancelled");}const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},2000)}
const dsIcsDate=d=>`${d.getFullYear()}${String(d.getMonth()+1).padStart(2,"0")}${String(d.getDate()).padStart(2,"0")}`;
function dsIcs(d){const T=dsTimeline(d).filter(x=>x.d&&x.days!=null&&x.days>=-1);const ev=T.map((x,i)=>["BEGIN:VEVENT",`UID:${d.id}-${i}@vanessa`,`DTSTAMP:${dsIcsDate(new Date())}T000000Z`,`DTSTART;VALUE=DATE:${dsIcsDate(x.d)}`,`DTEND;VALUE=DATE:${dsIcsDate(dsAddDays(x.d,1))}`,`SUMMARY:${(d.name+": "+String(x.what)).replace(/[\n,;]/g," ").slice(0,140)}`,`DESCRIPTION:${String(x.what).replace(/[\n,;]/g," ").slice(0,600)}`,"BEGIN:VALARM","TRIGGER:-P2D","ACTION:DISPLAY","DESCRIPTION:Deadline in 2 days","END:VALARM","END:VEVENT"].join("\r\n"));return["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//VANESSA//Doc Screener//EN",...ev,"END:VCALENDAR"].join("\r\n")}
const dsCsvCell=v=>`"${String(v==null?"":v).replace(/"/g,'""')}"`;
function dsReport(d){const ai=d.ai||{};const P=[{t:"Document Screening Report",h:1},{t:`${d.name} — ${d.type.n} — risk ${d.risk}/100${ai.verdict?" — "+ai.verdict:""}`,b:1},{t:`Screened ${new Date().toLocaleString()} by VANESSA for Steven Shearrill. Screening aid only; not legal advice. Verify loan rules against the current guide and the lender.`}];
 const sec=(h,a,f)=>{if(!a||!a.length)return;P.push({t:h,h:1});a.forEach(x=>P.push({t:"• "+(f?f(x):String(x))}))};
 if(ai.summary){P.push({t:"Executive summary",h:1},{t:ai.summary})}if(ai.client_summary){P.push({t:"Client summary",h:1},{t:ai.client_summary})}
 sec("Red flags",ai.red_flags,x=>`[${x.severity}] ${x.what} — ${x.why||""} Action: ${x.action||""}${x.quote?` Quote: "${x.quote}"`:""}`);
 sec("Forensics (hidden or altered content)",(d.forensic||[]).concat(d.scan.odd),f=>`${f.sev===3?"[HIGH]":f.sev===2?"[MED]":"[LOW]"} ${f.t}${f.q?" — "+f.q:""}`);
 sec("Hidden or unusual terms",ai.hidden,x=>`${x.what} — ${x.why||""}${x.quote?` "${x.quote}"`:""}`);
 sec("Timeline and deadlines",dsTimeline(d),x=>`${x.d?x.d.toLocaleDateString():x.lab}: ${x.what}`);
 sec("Key terms",ai.key_terms,k=>`${k.term}: ${k.value}`);sec("Money",ai.money,x=>`${x.amount} — ${x.what}${x.who_pays?` (${x.who_pays})`:""}`);
 sec("Clauses",(ai.clauses||[]).length?ai.clauses:d.scan.hits,c=>c.plain_english!==undefined?`[${c.severity}] ${c.name}: ${c.plain_english} Action: ${c.action||""}`:`[${c.sev===3?"high":c.sev===2?"medium":"low"}] ${c.n}: ${c.why} Do: ${c.act} — "${c.ms[0].ctx.slice(0,200)}"`);
 sec("Obligations",ai.obligations,o=>`${o.party}: ${o.must}${o.by?` (by ${o.by})`:""}`);sec("Missing / inconsistent",(ai.missing||[]).concat(ai.inconsistencies||[]));sec("Negotiation points",ai.negotiation_points);sec("Questions to ask",ai.questions);sec("Next steps",ai.next_steps);sec(`What to verify for a ${d.type.n}`,d.type.chk);
 return P}
