/* ---------------- agent tools, playbook, seats, squad, runbook, search ---------------- */
if(typeof PB_TOOLS==="function"){const t0=PB_TOOLS;PB_TOOLS=()=>[...t0(),
 {name:"doc_screen_current",description:"Results of the document currently open in the Document Screener: name, type, risk score, verdict and summary (if deep-screened), red flags, forensic findings (hidden or altered content), the timeline of dates and deadlines, and matched clause rules. Use it to answer questions about an uploaded document.",inputSchema:{type:"object",properties:{}},execute:()=>{const d=dsDoc();if(!d)return{error:"No document is open in the Document Screener."};return{name:d.name,type:d.type.n,risk:d.risk,verdict:d.ai&&d.ai.verdict,summary:d.ai&&d.ai.summary,red_flags:d.ai?(d.ai.red_flags||[]).slice(0,12):d.scan.hits.filter(h=>h.sev===3).map(h=>h.n),forensics:(d.forensic||[]).concat(d.scan.odd).map(f=>f.t),timeline:dsTimeline(d).slice(0,25).map(x=>({date:x.d?x.d.toISOString().slice(0,10):x.lab,what:String(x.what).slice(0,200)})),clauses:d.scan.hits.map(h=>`${h.n} (${h.sev===3?"high":h.sev===2?"medium":"low"})`)}}},
 {name:"doc_screen_text",description:"Run the instant rule screen on a piece of text (contract clause, email, conditions list): returns matched risk rules with why/what-to-do, dates, relative deadlines, amounts, blanks and hidden-character warnings.",inputSchema:{type:"object",properties:{text:{type:"string"}},required:["text"]},execute:i=>{const s=dsScan(String(i.text||"").slice(0,200000));return{type:dsType(String(i.text||"")).n,rules:s.hits.map(h=>({rule:h.n,severity:h.sev,why:h.why,do:h.act,quote:h.ms[0].ctx.slice(0,200)})),dates:s.dates.slice(0,30).map(x=>x.raw),periods:s.rel.slice(0,30).map(x=>x.raw),amounts:s.money.slice(0,30).map(x=>x.raw),blanks:s.blanks.length,warnings:s.odd.map(o=>o.t)}}},
 {name:"doc_screen_history",description:"Recent document screenings (name, type, risk, high flags, summary, next deadlines).",inputSchema:{type:"object",properties:{}},execute:()=>store.get("ds_hist",[]).slice(0,15)}]}
if(typeof PB_RUNS!=="undefined"&&!PB_RUNS.some(r=>r.k==="docscreen")){PB_RUNS.push({k:"docscreen",n:"🔬 Screen a document",d:"Upload any contract, disclosure, statement or agreement; get hidden content, every date and deadline, clauses, red flags and a full summary.",uses:["Claude"]});PB_UI.docscreen=()=>`<p class="sm">${store.get("ds_hist",[]).length} screenings on record · ${DS_RULES.length} rules.</p><button class="btn sm" id="pb_go">Open the Document Screener</button>`;PB_GO.docscreen=async()=>{location.hash="docscreen"}}
if(typeof AI_SEATS!=="undefined")[{n:"Document Forensics Screener",r:"Screens every incoming document for hidden or altered content (hidden/white text, tracked changes, edits after creation, editing-tool producers, JavaScript, look-alike letters, changed wire instructions) and fraud red flags on statements and paystubs",a:"VANESSA › Document Screener · agent tools doc_screen_current / doc_screen_text",b:"Howard",t:"ops"},{n:"Contract & Deadline Analyst",r:"Pulls every date, contingency and time period into a calendar, explains each clause in plain English, finds what shifts risk or money, and drafts negotiation points and client summaries",a:"VANESSA › Document Screener (Deep screen, Ask the document, Compare)",b:"Diane",t:"ops"}].forEach(s=>{if(!AI_SEATS.some(x=>x.n===s.n))AI_SEATS.push(s)});
if(typeof AI_SQUADS!=="undefined"){const d=AI_SQUADS.find(x=>x.k==="deal");if(d&&!d.lanes.some(l=>l[0]==="Document Forensics Screener"))d.lanes.push(["Document Forensics Screener","Docs","Hidden content, alterations, deadlines and clauses in the file's documents"])}
if(typeof RB!=="undefined"){[{k:"docscreen",n:"Screen every document before you rely on it",cat:"Origination",when:"Every purchase contract, counter, addendum, LE/CD, appraisal, title prelim, HOA packet, bank statement, paystub, vendor/lender agreement — on receipt",inputs:["The file (PDF, .docx, photo/scan or text)","Acceptance / start date"],steps:["Open Document Screener; drop the file(s)","Set the anchor date so every 'within N days' becomes a date","Read Forensics first: any 🔴 hidden/altered item stops the file until resolved","Deep screen with Claude (mask on)","Timeline → .ics or Board; red flags → Board","Compare against the prior version (counter vs contract, LE vs CD)","Send the client summary only after you review it"],outputs:["Risk score and verdict","Timeline in your calendar","Red flags on the board","Word report in the file"],conn:["Claude","Gmail (draft)"],owner:"Document Forensics Screener",backup:"Contract & Deadline Analyst",squad:"Deal Desk Squad",kpi:["Missed contingency deadlines: zero","Altered-document catches before UW","Time from receipt to screened < 10 min"],guard:["Screening aid, not legal advice — contract questions go to an attorney","Mask SSNs/account numbers; borrower files fall under the GLBA Safeguards Rule","Verify any wire instruction by phone with a known number"],fail:[["PDF has no text","Deep screen reads it as images; or ask for a digital copy"],["Library didn't load","You're offline or blocked; paste the text instead"]]}].forEach(r=>{if(!RB.some(x=>x.k===r.k))RB.push(r)})}
if(typeof SEARCH_ROUTES!=="undefined")SEARCH_ROUTES.unshift([/^(Doc(ument)? screen|screen (a )?doc)/i,{hash:"docscreen"}]);
